js.text:

function grid$thnxk(f){
  this.constructor(f);
}
grid$thnxk.prototype = new DirEvent();
grid$thnxk.prototype.afterInitFields = function(){
  var p = this._dir;
}
grid$thnxk.prototype.beforeInit = function(){
  var p = this._dir;
}
grid$thnxk.prototype.afterInit = function(){
  var p = this._dir, g = p.grid(), dt = g.data;
  if (p.options._data_analysis_struct == '') {
    p.setColumnHidden(0, ['tien_nhap', 'tien_xuat', 'tien_nt_nhap', 'tien_nt_xuat'], false);
    if (p.options._mau_bc == 1) p.setColumnHidden(0, ['tien_nhap', 'tien_xuat', 'tien_nt_nhap', 'tien_nt_xuat'], true);
    if (p.options._mau_bc == 2) p.setColumnHidden(0, ['tien_nt_nhap', 'tien_nt_xuat'], true);
    if (p.options._ct_nxd == '1') p.setColumnHidden(0, ['sl_xuat', 'tien_xuat', 'tien_nt_xuat'], true);
    if (p.options._ct_nxd == '2') p.setColumnHidden(0, ['sl_nhap', 'tien_nhap', 'tien_nt_nhap'], true);
  }
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
